vec2 L = vec2(1., sqrt(3.));

float hash12(vec2 p)
{
	vec3 p3 = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 nearestHexagonCenter(vec2 uv) {
    vec2 p1 = (floor(uv/L)+0.5)*L;
    vec2 p2 = floor(uv/L+0.5)*L;
    return dot(uv-p1,uv-p1) < dot(uv-p2,uv-p2) ?
        p1 : p2;
}

float circle(vec2 uv, vec2 center) {
    float r = 0.5/L.y;
    return (abs(distance(uv, center) - r));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - iResolution.xy * 0.5)/iResolution.xx;
    uv *= 20.0;
    uv += iTime * vec2(0.5, 0.7);
    vec2 center = nearestHexagonCenter(uv);
    vec2 c1 = vec2(0.5)/L;
    vec2 c2 = vec2(-0.5,0.5)/L;
    vec2 c3 = vec2(0,-1)/L;
    // Randomly flip hexagon
    if (hash12(center) < 0.5) {
        c1 *= -1.; c2 *= -1.; c3 *= -1.;
    }
    float f = min(min(circle(uv, center+c1), circle(uv, center+c2)), circle(uv, center+c3));

    vec3 col = vec3(2.0, 1.5, 0.5) * 0.01 * 1. / f;

    // Output to screen
    fragColor = vec4(col,1.0);
}
